// Concatenates src/*.js into long-con.bundle.js, a classic (non-module) script.
// Chrome refuses ES modules on file://, so index.html falls back to this file
// when src/main.js fails to load. The game itself needs no build step: the
// bundle is committed, and test/ui.test.js fails if it is out of date.
// Usage: node scripts/bundle.js            (writes the bundle)
//        import { buildBundle } from ...   (returns the text)
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const ORDER = ['tuning.js', 'content.js', 'marks.js', 'sim.js', 'ui.js', 'main.js'];

export function buildBundle() {
  const seen = new Map();
  const parts = ORDER.map((file) => {
    let src = readFileSync(join(ROOT, 'src', file), 'utf8');
    src = src.replace(/^import\s[\s\S]*?from\s+['"][^'"]+['"];\s*$/gm, '');
    src = src.replace(/^export\s+(?=(async\s+)?function|const|let|class)/gm, '');
    if (/^\s*(import|export)\s/m.test(src)) throw new Error(`bundle: unhandled import/export in ${file}`);
    for (const [, name] of src.matchAll(/^(?:async\s+)?(?:function\*?|const|let|class)\s+([A-Za-z_$][\w$]*)/gm)) {
      if (seen.has(name)) throw new Error(`bundle: ${name} declared in both ${seen.get(name)} and ${file}`);
      seen.set(name, file);
    }
    return `// ---- src/${file} ----\n${src.trim()}\n`;
  });
  return `// GENERATED by scripts/bundle.js from src/. Do not edit; run \`npm run bundle\`.\n(function () {\n'use strict';\n${parts.join('\n')}})();\n`;
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  writeFileSync(join(ROOT, 'long-con.bundle.js'), buildBundle());
  console.log('wrote long-con.bundle.js');
}
